data.query:
query Query($where: DataModelWhereInput, $orderBy: [DataModelOrderByInput!], $first: Int, $after: String) {
  dataModel(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        name
      }
    }
  }
}

query Query($where: DataModelWhereInput, $orderBy: [DataModelOrderByInput!], $first: Int, $after: String) {
