query Query(  
  $where: DataModelWhereInput,
  $orderBy: [DataModelOrderByInput!],
  $first: Int,
  $after: String
) {  
  dataModel(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        name
        description
      }
    }
  }
}

data.transform:
(
  $auditFields := [
    "createdAt",
    "createdByUserId",
    "createdByUser",
    "updatedAt",
    "updatedByUserId",
    "updatedByUser"
  ];

  $headers := [
    {
      "text": "Name"
    },
    {
      "text": "Type"
    },
    {
      "text": "Required"
    },
    {
      "text": "Unique"
    },
    {
      "text": "Description",
      "attrs": {
        "colwidth": [
          1195
        ]
      }
    }
  ];

  $formatTableHeader := function($text, $attrs){
    {
      "type": "tableHeader",
      "attrs": {
        "colspan": 1,
        "rowspan": 1,
        "colwidth": [
          $isNilOrEmpty($attrs.colwidth) ? 150 : $attrs.colwidth
        ]
      },
      "content": [
        {
          "type": "paragraph",
          "content": [
            {
              "text": $text,
              "type": "text",
              "marks": [
                {
                  "type": "strong"
                }
              ]
            }
          ]
        }
      ]
    }
  };

  $formatTableHeaderParagraph := function() {
    {
      "type": "tableRow",
      "content": [
        $headers.(
          $formatTableHeader(text, attrs)
        )
      ]
    }
  };

  $formatTableCell := function($v){
    {
      "type": "tableCell",
      "content": [
        {
          "type": "paragraph",
          "content": [
            {
              "text": $v,
              "type": "text"
             }
           ]
         }
       ]
     }
  };

  $formatTableCellHeading := function($v){
    {
      "type": "tableCell",
      "content": [
        {
          "type": "heading",
          "attrs":{
            "level": 4
          },
          "content": [
            {
              "text": $v,
              "type": "text"
             }
           ]
         }
       ]
     }
  };

  $formatTableRowParagraph := function($v) {  
    {
      "type": "tableRow",
      "content": [
        $formatTableCellHeading($v.name),
        $formatTableCell($v.metadata.type.base),
        $formatTableCell($v.metadata.type.nonNull ? "Yes" : "No"),
        $formatTableCell($v.metadata.unique ? "Yes" : "No"),
        $formatTableCell($v.description)
      ]
    }
  };

  $createDoc := function($modelDescriptions, $fieldTable,$auditTable){
    {
      "type": "doc",
      "content": [
        $filter($modelDescriptions,function($v){$isNilOrEmpty($v.text)~>$not}).{ 
          "type": "paragraph",
          "content": [
            {
              "text": text,
              "type": "text",
              "marks": strong ? [
                {
                  "type": "strong"
                }
              ]
            }
          ]
        },
        {
          "type": "extension",
          "attrs": {
            "layout": "default",
            "extensionType": "com.atlassian.confluence.macro.core",
            "extensionKey": "toc",
            "parameters": {
              "macroParams": {},
              "macroMetadata": {
                "macroId": {
                  "value": "d583e4e2-4794-4159-ab76-58c7743be55c"
                },
                "schemaVersion": {
                  "value": "1"
                },
                "title": "Table of Contents"
              }
            },
            "localId": "215f8d16-85ee-4bdb-a58e-4825b3d975f3"
          }
        },
        {
          "type": "heading",
          "attrs": {
            "level": 2
          },
          "content": [
            {
              "text": "Table Definition",
              "type": "text"
            }
          ]
        },
        {
          "type": "table",
          "content": $fieldTable
        },
        {
          "type": "heading",
          "attrs": {
            "level": 2
          },
          "content": [
            {
              "text": "Audit Fields",
              "type": "text"
            }
          ]
        },
        {
          "type": "table",
          "content": $auditTable
        },
        {
          "type": "paragraph"
        }
      ],
      "version": 1
    }
  };

  $filterOutAuditFields := function($fields) {
    $filter(
      $fields,
      function($v){
        $not($v.name in [$auditFields])
      }
    )
  };

  $getAuditFields := function($fields) {
    $filter(
      $fields,
      function($v){
        $v.name in [$auditFields]
      }
    )
  };

  $formatDataChangeCaptureMessage := function($dataChangeCapture) {
    (
      $exposed := $dataChangeCapture.exposed;
      $retentionDays := $dataChangeCapture.retentionDays;

      $exposed = true ? 
      "Data Changes are exposed and will be retained for " & $retentionDays & " days"
      :
      "Data Changes are not enabled on this model" 
    )  
  };

  $state.context ~> | dataModels | {
    "pageTitle": $singularize($state.context.CONSTANTS.CONFLUENCE.parentPageTitle, 'en') & ": " & name,
    "confluenceDocument": $createDoc(
      [{"text": description, "strong": false}, {"text": $formatDataChangeCaptureMessage(metadata.mfgx.dataChangeCapture), "strong": true}],
      $append(
        [$formatTableHeaderParagraph()],
        $filterOutAuditFields([fields]).(
          [$formatTableRowParagraph($)]
        )
      ),
      $append(
        [$formatTableHeaderParagraph()],
        $getAuditFields([fields]).(
          [$formatTableRowParagraph($)]
        )
      )
    )
  } |;
)

data.requestTransform:
$state.context.CONSTANTS.CONFLUENCE.parentPage.{
  "method": "put",
  "path": "/wiki/api/v2/pages/" & id,
  "body": {
    "id": id,
    "spaceId": $state.context.CONSTANTS.CONFLUENCE.spaceId,
    "status": "current",
    "title": title,
    "version": {
      "number": version.number + 1,
      "message": "Auto Generated Update By Fuuz"
    },
    "body": {
      "value": $jsonStringify(
        {
          "type":"doc",
          "content": [
            {
              "type": "paragraph",
              "content": [
                {
                  "text": $state.context.CONSTANTS.CONFLUENCE.appDescription,
                  "type": "text"
                 }
               ]
            }
          ]
        }
      ),
      "representation": "atlas_doc_format"
    }
  }
}

